-- public.chatbot_aspirational_districts source

CREATE MATERIALIZED VIEW public.chatbot_aspirational_districts
TABLESPACE pg_default
AS SELECT aspirational_districts.id,
    aspirational_districts.state_name,
    aspirational_districts.district_name,
    aspirational_districts.status
   FROM aspirational_districts
WITH DATA;

-- View indexes:
CREATE INDEX idx_chatbot_asp_districts_active_partial ON public.chatbot_aspirational_districts USING btree (state_name, district_name) WHERE (status = 1);
CREATE UNIQUE INDEX idx_chatbot_asp_districts_id ON public.chatbot_aspirational_districts USING btree (id);
CREATE INDEX idx_chatbot_asp_districts_state_district ON public.chatbot_aspirational_districts USING btree (state_name, district_name);
